 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Fill rectangular hollow frames; interiors are mapped by cavity size.
    seen = set()
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == 4 or (r, c) in seen:
                continue
            # Find same-color connected component.
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop(); cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and g[yy][xx] == color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            # A hollow rectangle outline occupies the full bbox perimeter.
            if len(cells) == 2*(r1-r0+1)+2*(c1-c0+1)-4:
                iw, ih = c1-c0-1, r1-r0-1
                fill = 2 if (ih,iw)==(2,2) else 7
                for y in range(r0+1,r1):
                    for x in range(c0+1,c1):
                        if g[y][x] == 4: g[y][x] = fill
    return g

if __name__ == '__main__':
    pass
